import{_ as e,c as t,o as a,a0 as r}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"sv/blog/inner-critic.md","filePath":"sv/blog/inner-critic.md"}');const i=e({name:"sv/blog/inner-critic.md"},[["render",function(e,n,i,l,s,d){return a(),t("div",null,[...n[0]||(n[0]=[r('<h1 id="att-forsta-den-inre-kritikern" tabindex="-1">Att förstå den inre kritikern <a class="header-anchor" href="#att-forsta-den-inre-kritikern" aria-label="Permalink to &quot;Att förstå den inre kritikern&quot;">​</a></h1><p>Varje boulespelare känner till den rösten. Den som viskar &quot;du kommer att missa&quot; precis när du ska kasta. Den som spelar upp ditt senaste misslyckade slag i en oändlig loop. Detta är din inre kritiker – och att lära sig hantera den är avgörande för elitprestationer.</p><h2 id="vad-ar-den-inre-kritikern" tabindex="-1">Vad är den inre kritikern? <a class="header-anchor" href="#vad-ar-den-inre-kritikern" aria-label="Permalink to &quot;Vad är den inre kritikern?&quot;">​</a></h2><p>Den inre kritikern är den inre rösten som dömer, kritiserar och undergräver ditt självförtroende. I boule dyker den ofta upp i de värsta tänkbara ögonblicken:</p><ul><li><strong>Innan ett avgörande skott</strong>: &quot;Alla tittar. Stör inte till det här.&quot;</li><li><strong>Efter en miss</strong>: &quot;Du kvävs alltid av press.&quot;</li><li><strong>Under en förlustsvit</strong>: &quot;Du är inte tillräckligt bra för den här nivån.&quot;</li></ul><p>Den här rösten försöker inte skada dig – det är faktiskt ett missriktat försök till skydd. Din hjärna försöker förbereda dig för misslyckande så att det inte ska göra lika ont. Men detta &quot;skydd&quot; blir till självsabotage.</p><h2 id="att-kanna-igen-dina-monster" tabindex="-1">Att känna igen dina mönster <a class="header-anchor" href="#att-kanna-igen-dina-monster" aria-label="Permalink to &quot;Att känna igen dina mönster&quot;">​</a></h2><p>Det första steget är medvetenhet. Börja lägga märke till när din inre kritiker dyker upp:</p><h3 id="vanliga-utlosare" tabindex="-1">Vanliga utlösare <a class="header-anchor" href="#vanliga-utlosare" aria-label="Permalink to &quot;Vanliga utlösare&quot;">​</a></h3><ul><li>Högpressade situationer (matchboll, viktiga turneringar)</li><li>Efter att ha gjort ett misstag</li><li>När motståndarna presterar bra</li><li>När lagkamraterna verkar frustrerade</li><li>Fysisk trötthet eller obehag</li></ul><h3 id="vanliga-meddelanden" tabindex="-1">Vanliga meddelanden <a class="header-anchor" href="#vanliga-meddelanden" aria-label="Permalink to &quot;Vanliga meddelanden&quot;">​</a></h3><ul><li>&quot;Du klarar inte av press&quot;</li><li>&quot;Du är inte lika bra som dem&quot;</li><li>&quot;Alla dömer dig&quot;</li><li>&quot;Du misslyckas alltid när det gäller&quot;</li></ul><h2 id="paverkan-pa-prestanda" tabindex="-1">Påverkan på prestanda <a class="header-anchor" href="#paverkan-pa-prestanda" aria-label="Permalink to &quot;Påverkan på prestanda&quot;">​</a></h2><p>När den inre kritikern tar över, reagerar din kropp:</p><ol><li><strong>Muskelspänningen ökar</strong> — Ditt kast blir stelt</li><li><strong>Andningen blir ytlig</strong> — Mindre syre, mindre fokus</li><li><strong>Synen försvagas</strong> — Du förlorar medvetenheten om terrängen</li><li><strong>Beslutsfattandet lider</strong> — Du tvivlar på dig själv</li></ol><p>Detta skapar en ond cirkel: den inre kritikern orsakar dåliga prestationer, vilket ger kritikern mer ammunition.</p><h2 id="strategier-for-att-hantera-den-inre-kritikern" tabindex="-1">Strategier för att hantera den inre kritikern <a class="header-anchor" href="#strategier-for-att-hantera-den-inre-kritikern" aria-label="Permalink to &quot;Strategier för att hantera den inre kritikern&quot;">​</a></h2><h3 id="_1-namnge-det-for-att-tamja-det" tabindex="-1">1. Namnge det för att tämja det <a class="header-anchor" href="#_1-namnge-det-for-att-tamja-det" aria-label="Permalink to &quot;1. Namnge det för att tämja det&quot;">​</a></h3><p>Ge din inre kritiker ett namn – något lite löjligt. ”Åh, där går Negative Nils igen.” Detta skapar distans mellan dig och rösten, vilket gör den lättare att avfärda.</p><h3 id="_2-utmana-bevisen" tabindex="-1">2. Utmana bevisen <a class="header-anchor" href="#_2-utmana-bevisen" aria-label="Permalink to &quot;2. Utmana bevisen&quot;">​</a></h3><p>När kritikern säger &quot;du misslyckas alltid under press&quot;, fråga dig själv: Är det verkligen sant? Kan du komma på tillfällen då du presterade bra under press? Kritikern använder sig av absoluta värden som sällan återspeglar verkligheten.</p><h3 id="_3-omformulera-meddelandet" tabindex="-1">3. Omformulera meddelandet <a class="header-anchor" href="#_3-omformulera-meddelandet" aria-label="Permalink to &quot;3. Omformulera meddelandet&quot;">​</a></h3><p>Omvandla kritik till coachning:</p><ul><li>&quot;Du kommer att sakna&quot; → &quot;Fokusera på din rutin&quot;</li><li>&quot;Alla tittar&quot; → &quot;Det här är ditt ögonblick att glänsa&quot;</li><li>&quot;Du kvävs alltid&quot; → &quot;Du har hanterat press förut&quot;</li></ul><h3 id="_4-anvand-din-rutin-fore-skott" tabindex="-1">4. Använd din rutin före skott <a class="header-anchor" href="#_4-anvand-din-rutin-fore-skott" aria-label="Permalink to &quot;4. Använd din rutin före skott&quot;">​</a></h3><p>En gedigen <a href="/sv/utbildning/mental-styrka/rutin-före-sprutan">rutin före sprutan</a> ger ditt sinne något konstruktivt att fokusera på, vilket lämnar mindre utrymme för kritikern.</p><h3 id="_5-ova-sjalvmedkansla" tabindex="-1">5. Öva självmedkänsla <a class="header-anchor" href="#_5-ova-sjalvmedkansla" aria-label="Permalink to &quot;5. Öva självmedkänsla&quot;">​</a></h3><p>Behandla dig själv som du skulle behandla en lagkamrat. Skulle du säga till en lagkamrat som kämpar &quot;du är hemsk&quot;? Självklart inte. Visa samma vänlighet mot dig själv.</p><h2 id="att-bygga-en-stodjande-inre-rost" tabindex="-1">Att bygga en stödjande inre röst <a class="header-anchor" href="#att-bygga-en-stodjande-inre-rost" aria-label="Permalink to &quot;Att bygga en stödjande inre röst&quot;">​</a></h2><p>Målet är inte att tysta den inre kritikern helt – det är nästan omöjligt. Utveckla istället en starkare stödjande röst:</p><h3 id="den-stodjande-rosten-sager" tabindex="-1">Den stödjande rösten säger: <a class="header-anchor" href="#den-stodjande-rosten-sager" aria-label="Permalink to &quot;Den stödjande rösten säger:&quot;">​</a></h3><ul><li>&quot;Ett kast i taget&quot;</li><li>&quot;Lita på din träning&quot;</li><li>&quot;Du har gjort det här förut&quot;</li><li>&quot;Stanna kvar i nuet&quot;</li><li>&quot;Andas och återställ&quot;</li></ul><h3 id="daglig-ovning" tabindex="-1">Daglig övning <a class="header-anchor" href="#daglig-ovning" aria-label="Permalink to &quot;Daglig övning&quot;">​</a></h3><p>Tillbringa 5 minuter varje dag:</p><ol><li>Minns ett ögonblick när du presterade bra</li><li>Kom ihåg hur det kändes i din kropp</li><li>Hör vad din stödjande röst sa</li><li>Förankra denna känsla med en fysisk gest (att röra vid din boule, justera din ställning)</li></ol><h2 id="i-tavling" tabindex="-1">I tävling <a class="header-anchor" href="#i-tavling" aria-label="Permalink to &quot;I tävling&quot;">​</a></h2><p>När den inre kritikern dyker upp under en match:</p><ol><li><strong>Erkänn det</strong>: &quot;Jag märker att jag är självkritisk&quot;</li><li><strong>Ta ett andetag</strong>: Långsamt, djupt andetag för att återställa</li><li><strong>Använd ditt ankare</strong>: Den fysiska gesten från din praktik</li><li><strong>Återgå till rutinen</strong>: Fokusera på din process före behandlingen</li></ol><h2 id="den-langsiktiga-resan" tabindex="-1">Den långsiktiga resan <a class="header-anchor" href="#den-langsiktiga-resan" aria-label="Permalink to &quot;Den långsiktiga resan&quot;">​</a></h2><p>Att hantera den inre kritikern är inte en engångslösning. Det är en pågående övning som blir lättare med tiden. Elitspelare eliminerar inte självtvivel – de lär sig att prestera trots det.</p><p>Den inre kritikern kommer alltid att vara en del av dig. Men med övning blir dess röst tystare och din stödjande röst starkare. Det är den mentala fördelen som skiljer bra spelare från fantastiska.</p><hr><p>| <em>Relaterat: <a href="/sv/utbildning/mental-styrka/hantera-press">Hantera press</a> | <a href="/sv/utbildning/mental-styrka/rutin-före-skott">Rutin före skott</a> | <a href="/sv/utbildning/mindfulness/tekniker">Mindfulnesstekniker</a></em> |</p>',43)])])}]]);export{n as __pageData,i as default};
